base.modules/app/main.tf:
variable "name" {
  type = string
}
variable "retention" {
  type    = number
  default = 14
}
variable "subnet_ids" {
  type    = list(string)
  default = []
}
resource "aws_cloudwatch_log_group" "g" {
  name              = var.name
  retention_in_days = var.retention
}

base.env/root.hcl:
locals {
  region = "ca-central-1"
}
inputs = {
  region    = local.region
  retention = 30
}

base.env/cloud/app/terragrunt.hcl:
terraform {
  source = "../../../modules//app"
}
include "root" {
  path = find_in_parent_folders("root.hcl")
}
locals {
  prefix = "forms"
}
inputs = {
  name = "${local.prefix}-app"
}

